import { Buffer } from 'buffer'
import { Minipass } from 'minipass'
import * as realZlib from 'zlib'
import { constants } from './constants.js'
export { constants } from './constants.js'

const OriginalBufferConcat = Buffer.concat
const desc = Object.getOwnPropertyDescriptor(Buffer, 'concat')
const noop = (args: Buffer[]) => args as unknown as Buffer
const passthroughBufferConcat =
  desc?.writable === true || desc?.set !== undefined
    ? (makeNoOp: boolean) => {
        Buffer.concat = makeNoOp ? noop : OriginalBufferConcat
      }
    : (_: boolean) => {}

const _superWrite = Symbol('_superWrite')

export class ZlibError extends Error {
  code?: string
  errno?: number
  constructor(err: NodeJS.ErrnoException | Error, origin?: Function) {
    super('zlib: ' + err.message, { cause: err })
    this.code = (err as NodeJS.ErrnoException).code
    this.errno = (err as NodeJS.ErrnoException).errno
    /* c8 ignore next */
    if (!this.code) this.code = 'ZLIB_ERROR'

    this.message = 'zlib: ' + err.message
    Error.captureStackTrace(this, origin ?? this.constructor)
  }

  get name() {
    return 'ZlibError'
  }
}

// the Zlib class they all inherit from
// This thing manages the queue of requests, and returns
// true or false if there is anything in the queue when
// you call the .write() method.
const _flushFlag = Symbol('flushFlag')

export type ChunkWithFlushFlag = Minipass.ContiguousData & {
  [_flushFlag]?: number
}

export type ZlibBaseOptions = Minipass.Options<Minipass.ContiguousData> & {
  flush?: number
  finishFlush?: number
  fullFlushFlag?: number
}

export type ZlibHandle =
  | realZlib.Gzip
  | realZlib.Gunzip
  | realZlib.Deflate
  | realZlib.Inflate
  | realZlib.DeflateRaw
  | realZlib.InflateRaw
  | realZlib.BrotliCompress
  | realZlib.BrotliDecompress
  | realZlib.ZstdCompress
  | realZlib.ZstdDecompress
export type ZlibMode =
  | 'Gzip'
  | 'Gunzip'
  | 'Deflate'
  | 'Inflate'
  | 'DeflateRaw'
  | 'InflateRaw'
  | 'Unzip'
export type BrotliMode = 'BrotliCompress' | 'BrotliDecompress'
export type ZstdMode = 'ZstdCompress' | 'ZstdDecompress'

abstract class ZlibBase extends Minipass<Buffer, ChunkWithFlushFlag> {
  #sawError: boolean = false
  #ended: boolean = false
  #flushFlag: number
  #finishFlushFlag: number
  #fullFlushFlag: number
  #handle?: ZlibHandle
  #onError: (err: ZlibError) => any

  get sawError() {
    return this.#sawError
  }
  get handle() {
    return this.#handle
  }
  /* c8 ignore start */
  get flushFlag() {
    return this.#flushFlag
  }
  /* c8 ignore stop */

  constructor(opts: ZlibBaseOptions, mode: ZlibMode | BrotliMode | ZstdMode) {
    if (!opts || typeof opts !== 'object')
      throw new TypeError('invalid options for ZlibBase constructor')

    //@ts-ignore
    super(opts)

    /* c8 ignore start */
    this.#flushFlag = opts.flush ?? 0
    this.#finishFlushFlag = opts.finishFlush ?? 0
    this.#fullFlushFlag = opts.fullFlushFlag ?? 0
    /* c8 ignore stop */

    //@ts-ignore
    if (typeof realZlib[mode] !== 'function') {
      throw new TypeError('Compression method not supported: ' + mode)
    }

    // this will throw if any options are invalid for the class selected
    try {
      // @types/node doesn't know that it exports the classes, but they're there
      //@ts-ignore
      this.#handle = new realZlib[mode](opts)
    } catch (er) {
      // make sure that all errors get decorated properly
      throw new ZlibError(er as NodeJS.ErrnoException, this.constructor)
    }

    this.#onError = err => {
      // no sense raising multiple errors, since we abort on the first one.
      if (this.#sawError) return

      this.#sawError = true

      // there is no way to cleanly recover.
      // continuing only obscures problems.
      this.close()
      this.emit('error', err)
    }

    this.#handle?.on('error', er => this.#onError(new ZlibError(er)))
    this.once('end', () => this.close)
  }

  close() {
    if (this.#handle) {
      this.#handle.close()
      this.#handle = undefined
      this.emit('close')
    }
  }

  reset() {
    if (!this.#sawError) {
      assert(this.#handle, 'zlib binding closed')
      //@ts-ignore
      return this.#handle.reset?.()
    }
  }

  flush(flushFlag?: number) {
    if (this.ended) return

    if (typeof flushFlag !== 'number') flushFlag = this.#fullFlushFlag

    this.write(Object.assign(Buffer.alloc(0), { [_flushFlag]: flushFlag }))
