        // or else the Set would've been reused
        const n = q[0]
        if (typeof n === 'function') {
          next.add(n)
        }
      } else {
        q0.delete(fn)
      }
    }

    this.#running.delete(fn)
    next.forEach(fn => this.#run(fn))
