      const buf = Buffer.allocUnsafe(readSize)
      while (pos < stat.size) {
        const bytesRead = fs.readSync(fd, buf, 0, readSize, pos)
        if (bytesRead === 0) break
        pos += bytesRead
        p.write(buf.subarray(0, bytesRead))
      }
      p.end()
    }
