    this.blockRemain -= writeLen
    return super.write(chunk, cb)
  }

  end(cb?: () => void): this
  end(chunk: Buffer | string, cb?: () => void): this
  end(
    chunk: Buffer | string,
    encoding?: BufferEncoding,
    cb?: () => void,
  ): this
  end(
    chunk?: Buffer | string | (() => void),
    encoding?: BufferEncoding | (() => void),
    cb?: () => void,
  ): this {
